"use strict";
(()=>{
  const $=s=>document.querySelector(s),root=$("#mRoot"),scale=$("#mScale"),music=$("#mMusic"),preview=$("#mScalePreview"),summary=$("#mSummary");
  const names=["Do","Do♯","Ré","Mi♭","Mi","Fa","Fa♯","Sol","La♭","La","Si♭","Si"],intervals={blues:[0,3,5,6,7,10,12],major:[0,2,4,5,7,9,11,12],minor:[0,2,3,5,7,8,10,12],pentatonic:[0,2,4,7,9,12],minorPentatonic:[0,3,5,7,10,12]},labels={blues:"Blues",major:"Majeure",minor:"Mineure",pentatonic:"Penta. majeure",minorPentatonic:"Penta. mineure"},fingers=[[],[1,2,3],[1,3],[2,3],[1,2],[1],[2],[],[2,3],[1,2],[1],[2]];
  let source="scale",mode="hero",audio=null;
  function tone(midi){audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const n=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type="triangle";o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(.001,n);g.gain.exponentialRampToValueAtTime(.18,n+.015);g.gain.exponentialRampToValueAtTime(.001,n+.45);o.connect(g).connect(audio.destination);o.start(n);o.stop(n+.46)}
  function render(){const base=(60+Number(root.value)>71?48:60)+Number(root.value);preview.innerHTML='<span class="m-preview-clef">𝄞</span><span class="m-preview-lines"></span>';for(const step of intervals[scale.value]){const midi=base+step,vals=fingers[midi%12],button=document.createElement("button");button.style.setProperty("--y",`${42-step*1.75}px`);button.innerHTML=`<i></i><b>${names[midi%12]}${Math.floor(midi/12)-1}</b><span>${(vals.length?vals:[0]).map(v=>`<em class="v${v}">${v}</em>`).join("")}</span>`;button.setAttribute("aria-label",`${names[midi%12]}, ${vals.length?`pistons ${vals.join(" et ")}`:"pistons libres"}`);button.onclick=()=>tone(midi);preview.appendChild(button)}update()}
  function update(){const modeName={hero:"Héros",instrument:"Instrument",partition:"Partition"}[mode];summary.textContent=source==="scale"?`${names[Number(root.value)]} · ${labels[scale.value]} · ${modeName}`:`${music.selectedOptions[0].textContent} · ${modeName}`}
  document.querySelectorAll("[data-tab]").forEach(tab=>tab.onclick=()=>{source=tab.dataset.tab;document.querySelectorAll("[data-tab]").forEach(x=>x.classList.toggle("active",x===tab));document.querySelectorAll("[data-panel]").forEach(p=>{const on=p.dataset.panel===source;p.hidden=!on;p.classList.toggle("active",on)});update()});
  document.querySelectorAll("[data-mode]").forEach(button=>button.onclick=()=>{mode=button.dataset.mode;document.querySelectorAll("[data-mode]").forEach(x=>x.classList.toggle("active",x===button));$("#mModeHint").textContent={hero:"Réflexes visuels",instrument:"Trompette en mouvement",partition:"Lecture sans distraction"}[mode];update()});
  root.onchange=render;scale.onchange=render;music.onchange=update;
  $("#mLaunch").onclick=()=>{const q=new URLSearchParams({mode});if(source==="scale"){q.set("root",root.value);q.set("scale",scale.value)}else q.set("track",music.value);location.href=`mobile-player.html?${q}`};render();
})();
